if (!defined('ABSPATH')) exit; final class Rocket_Request_Tracer { const VERSION='0.2.0'; const OPT_ENABLED='rrt_enabled'; const OPT_DEEP='rrt_deep_attribution'; const OPT_MAX_MB='rrt_max_log_mb'; const NONCE='rrt_admin_action'; private static $instance=null; private $enabled=false,$deep=false,$start_time=0.0,$pid=0,$request_id='',$log_file=''; private $start_event=array(),$resource_start=array(),$http_calls=array(),$http_pending=array(); public static function instance(){ if(self::$instance===null) self::$instance=new self(); return self::$instance; } private function __construct(){ $this->log_file=$this->get_log_file(); $this->enabled=(bool)get_option(self::OPT_ENABLED,false); $this->deep=(bool)get_option(self::OPT_DEEP,false); if($this->enabled && $this->should_trace_request()){ $this->prepare_deep_attribution(); $this->begin_trace(); } if(is_admin()){ add_action('admin_menu',array($this,'admin_menu')); add_action('admin_post_rrt_save',array($this,'handle_save')); add_action('admin_post_rrt_clear',array($this,'handle_clear')); add_action('admin_post_rrt_download',array($this,'handle_download')); } } private function should_trace_request(){ if(PHP_SAPI==='cli') return false; if(defined('WP_CLI') && WP_CLI) return false; if(defined('DOING_CRON') && DOING_CRON) return false; if(is_admin() && isset($_REQUEST['page']) && $_REQUEST['page']==='rocket-request-tracer') return false; if(isset($_REQUEST['action']) && in_array($_REQUEST['action'],array('rrt_save','rrt_clear','rrt_download'),true)) return false; return true; } private function prepare_deep_attribution(){ if(!$this->deep) return; global $wpdb; if(isset($wpdb) && is_object($wpdb) && property_exists($wpdb,'save_queries')) $wpdb->save_queries=true; add_filter('http_request_args',array($this,'http_request_start'),-9999,2); add_action('http_api_debug',array($this,'http_request_end'),9999,5); } public function http_request_start($args,$url){ $id=count($this->http_pending); $this->http_pending[$id]=array( 'url_raw'=>(string)$url, 'url'=>$this->sanitize_url($url), 'start'=>microtime(true), 'caller'=>function_exists('wp_debug_backtrace_summary')?wp_debug_backtrace_summary(null,0,false):null, 'done'=>false, ); return $args; } public function http_request_end($response,$context,$class,$parsed_args,$url){ $url=(string)$url;$match=null; foreach($this->http_pending as $id=>$pending){ if(!$pending['done'] && $pending['url_raw']===$url){$match=$id;break;} } if($match===null) return; $end=microtime(true);$pending=$this->http_pending[$match];$this->http_pending[$match]['done']=true; $code=null;$error=null; if(is_wp_error($response)) $error=$response->get_error_code(); elseif(is_array($response)) $code=wp_remote_retrieve_response_code($response); $this->http_calls[]=array( 'url'=>$pending['url'], 'duration_ms'=>round(($end-$pending['start'])*1000,3), 'response'=>$code,'error'=>$error,'caller'=>$pending['caller'], 'transport'=>is_object($class)?get_class($class):(is_string($class)?$class:null), ); } private function begin_trace(){ $this->start_time=microtime(true); $this->pid=function_exists('getmypid')?(int)getmypid():0; $this->resource_start=$this->resource_snapshot(); try{$random=bin2hex(random_bytes(3));}catch(Throwable $e){$random=substr(md5(uniqid('',true)),0,6);} $this->request_id=sprintf('%d-%s-%s',$this->pid,str_replace('.','',sprintf('%.6f',$this->start_time)),$random); $request_uri=isset($_SERVER['REQUEST_URI'])?(string)$_SERVER['REQUEST_URI']:''; $path=$request_uri!==''?parse_url($request_uri,PHP_URL_PATH):null; $query_string=isset($_SERVER['QUERY_STRING'])?(string)$_SERVER['QUERY_STRING']:''; $wp_action=(isset($_REQUEST['action'])&&is_scalar($_REQUEST['action']))?substr((string)$_REQUEST['action'],0,200):null; $wc_ajax=(isset($_GET['wc-ajax'])&&is_scalar($_GET['wc-ajax']))?substr((string)$_GET['wc-ajax'],0,200):null; $this->start_event=array( 'event'=>'START','version'=>self::VERSION,'timestamp'=>$this->utc_timestamp($this->start_time), 'request_id'=>$this->request_id,'pid'=>$this->pid, 'ppid'=>function_exists('posix_getppid')?@posix_getppid():null, 'uid'=>function_exists('posix_geteuid')?@posix_geteuid():null, 'method'=>isset($_SERVER['REQUEST_METHOD'])?$_SERVER['REQUEST_METHOD']:null, 'host'=>isset($_SERVER['HTTP_HOST'])?$_SERVER['HTTP_HOST']:null, 'path'=>$path,'query_keys'=>array_keys($_GET), 'query_hash'=>$query_string!==''?substr(hash('sha256',$query_string),0,16):null, 'safe_query'=>$this->safe_query_values($_GET),'wp_action'=>$wp_action,'wc_ajax'=>$wc_ajax, 'script'=>isset($_SERVER['SCRIPT_FILENAME'])?$_SERVER['SCRIPT_FILENAME']:null, 'cf_ray'=>$this->server_value('HTTP_CF_RAY',200), 'client_ip'=>$this->server_value('HTTP_CF_CONNECTING_IP',100)?:$this->server_value('REMOTE_ADDR',100), 'remote_ip'=>$this->server_value('REMOTE_ADDR',100), 'user_agent'=>$this->server_value('HTTP_USER_AGENT',1000), 'referer'=>$this->server_value('HTTP_REFERER',1000), 'content_type'=>$this->server_value('CONTENT_TYPE',200), 'content_length'=>isset($_SERVER['CONTENT_LENGTH'])?(int)$_SERVER['CONTENT_LENGTH']:null, 'deep'=>$this->deep, ); $this->write_event($this->start_event); register_shutdown_function(array($this,'end_trace')); } public function end_trace(){ if(!$this->enabled || !$this->request_id) return; $end_time=microtime(true);$resource_end=$this->resource_snapshot(); $resource_delta=$this->resource_delta($this->resource_start,$resource_end); $wall_ms=($end_time-$this->start_time)*1000; $cpu_ms=isset($resource_delta['cpu_total_ms'])?$resource_delta['cpu_total_ms']:null; $cpu_ratio=($cpu_ms!==null && $wall_ms>0)?min(10,$cpu_ms/$wall_ms):null; $last_error=error_get_last();$fatal=null; if($last_error && in_array($last_error['type'],array(E_ERROR,E_PARSE,E_CORE_ERROR,E_COMPILE_ERROR,E_USER_ERROR,E_RECOVERABLE_ERROR),true)){ $fatal=array('type'=>$last_error['type'],'message'=>$last_error['message'],'file'=>$last_error['file'],'line'=>$last_error['line']); } $sql=$this->deep?$this->sql_summary():array('count'=>null,'total_ms'=>null,'top'=>array()); $http=$this->deep?$this->http_summary():array('count'=>null,'total_ms'=>null,'top'=>array()); $event=array( 'event'=>'END','version'=>self::VERSION,'timestamp'=>$this->utc_timestamp($end_time), 'request_id'=>$this->request_id,'pid'=>$this->pid, 'method'=>isset($this->start_event['method'])?$this->start_event['method']:null, 'host'=>isset($this->start_event['host'])?$this->start_event['host']:null, 'path'=>isset($this->start_event['path'])?$this->start_event['path']:null, 'status'=>function_exists('http_response_code')?http_response_code():null, 'wall_ms'=>round($wall_ms,3), 'cpu_user_ms'=>isset($resource_delta['cpu_user_ms'])?$resource_delta['cpu_user_ms']:null, 'cpu_sys_ms'=>isset($resource_delta['cpu_sys_ms'])?$resource_delta['cpu_sys_ms']:null, 'cpu_total_ms'=>$cpu_ms,'cpu_ratio'=>$cpu_ratio!==null?round($cpu_ratio,4):null, 'classification'=>$this->classify_request($wall_ms,$cpu_ratio), 'peak_memory_mb'=>round(memory_get_peak_usage(true)/1048576,2), 'memory_end_mb'=>round(memory_get_usage(true)/1048576,2), 'included_files'=>count(get_included_files()),'included_groups'=>$this->included_file_groups(), 'resources'=>$resource_delta,'sql'=>$sql,'http'=>$http, 'connection_aborted'=>function_exists('connection_aborted')?connection_aborted():null,'fatal'=>$fatal, ); $this->write_event($event); } private function classify_request($wall_ms,$cpu_ratio){ if($wall_ms<750) return 'FAST'; if($cpu_ratio===null) return 'UNKNOWN'; if($cpu_ratio>=0.70) return 'CPU_BOUND'; if($cpu_ratio<=0.25) return 'WAIT_BOUND'; return 'MIXED'; } private function safe_query_values($input){ $out=array(); foreach($input as $key=>$value){ $key=(string)$key; $allowed=(strpos($key,'filter_')===0 || strpos($key,'query_type_')===0 || in_array($key,array('orderby','paged','page','product_cat','product_tag','min_price','max_price','s'),true)); if(!$allowed) continue; if(is_scalar($value)) $out[$key]=substr((string)$value,0,500); elseif(is_array($value)){ $vals=array();foreach(array_slice($value,0,20) as $v)$vals[]=is_scalar($v)?substr((string)$v,0,500):'[complex]';$out[$key]=$vals; } } return $out; } private function resource_snapshot(){ $out=array('cpu_user_ms'=>null,'cpu_sys_ms'=>null,'cpu_total_ms'=>null,'minor_faults'=>null,'major_faults'=>null,'voluntary_ctx'=>null,'involuntary_ctx'=>null,'block_in'=>null,'block_out'=>null,'rchar'=>null,'wchar'=>null,'read_bytes'=>null,'write_bytes'=>null,'syscr'=>null,'syscw'=>null); if(function_exists('getrusage')){ $r=getrusage(); $user=((isset($r['ru_utime.tv_sec'])?$r['ru_utime.tv_sec']:0)*1000)+((isset($r['ru_utime.tv_usec'])?$r['ru_utime.tv_usec']:0)/1000); $sys=((isset($r['ru_stime.tv_sec'])?$r['ru_stime.tv_sec']:0)*1000)+((isset($r['ru_stime.tv_usec'])?$r['ru_stime.tv_usec']:0)/1000); $out['cpu_user_ms']=$user;$out['cpu_sys_ms']=$sys;$out['cpu_total_ms']=$user+$sys; $out['minor_faults']=isset($r['ru_minflt'])?(int)$r['ru_minflt']:null; $out['major_faults']=isset($r['ru_majflt'])?(int)$r['ru_majflt']:null; $out['voluntary_ctx']=isset($r['ru_nvcsw'])?(int)$r['ru_nvcsw']:null; $out['involuntary_ctx']=isset($r['ru_nivcsw'])?(int)$r['ru_nivcsw']:null; $out['block_in']=isset($r['ru_inblock'])?(int)$r['ru_inblock']:null; $out['block_out']=isset($r['ru_oublock'])?(int)$r['ru_oublock']:null; } if(is_readable('/proc/self/io')){ $lines=@file('/proc/self/io',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES); if(is_array($lines)) foreach($lines as $line){ if(strpos($line,':')===false) continue;list($key,$value)=array_map('trim',explode(':',$line,2)); if(array_key_exists($key,$out)) $out[$key]=is_numeric($value)?(int)$value:null; } } return $out; } private function resource_delta($start,$end){ $out=array();foreach($end as $key=>$value){ $sv=isset($start[$key])?$start[$key]:null; if($value===null||$sv===null){$out[$key]=null;continue;} $d=$value-$sv;$out[$key]=strpos($key,'_ms')!==false?round($d,3):$d; }return $out; } private function sql_summary(){ global $wpdb;$result=array('count'=>0,'total_ms'=>0,'top'=>array()); if(!isset($wpdb->queries)||!is_array($wpdb->queries)) return $result; $rows=array(); foreach($wpdb->queries as $entry){ if(!is_array($entry)||!isset($entry[0],$entry[1])) continue; $sql=(string)$entry[0];$seconds=(float)$entry[1];$caller=isset($entry[2])?(string)$entry[2]:null; $rows[]=array('duration_ms'=>round($seconds*1000,3),'query'=>$this->sanitize_sql($sql),'query_hash'=>substr(hash('sha256',$sql),0,16),'caller'=>$caller); $result['total_ms']+=$seconds*1000; } usort($rows,function($a,$b){return $b['duration_ms']<=>$a['duration_ms'];}); $result['count']=count($rows);$result['total_ms']=round($result['total_ms'],3);$result['top']=array_slice($rows,0,10);return $result; } private function sanitize_sql($sql){ $sql=preg_replace("/'(?:''|\\\\'|[^'])*'/s","'?'",$sql); $sql=preg_replace('/"(?:\\\\"|[^"])*"/s','"?"',$sql); $sql=preg_replace('/\b\d+(?:\.\d+)?\b/','?',$sql); $sql=preg_replace('/\s+/',' ',trim($sql));return substr($sql,0,1200); } private function http_summary(){ $calls=$this->http_calls;usort($calls,function($a,$b){return $b['duration_ms']<=>$a['duration_ms'];});$total=0; foreach($calls as $call)$total+=$call['duration_ms']; return array('count'=>count($calls),'total_ms'=>round($total,3),'top'=>array_slice($calls,0,10)); } private function sanitize_url($url){ $p=wp_parse_url((string)$url);if(!is_array($p)) return substr((string)$url,0,1000); return substr((isset($p['scheme'])?$p['scheme'].'://':'').(isset($p['host'])?$p['host']:'').(isset($p['port'])?':'.$p['port']:'').(isset($p['path'])?$p['path']:''),0,1000); } private function included_file_groups(){ $groups=array();foreach(get_included_files() as $file){ if(preg_match('#/wp-content/mu-plugins/([^/]+)/#',$file,$m))$group='mu-plugin:'.$m[1]; elseif(preg_match('#/wp-content/plugins/([^/]+)/#',$file,$m))$group='plugin:'.$m[1]; elseif(preg_match('#/wp-content/themes/([^/]+)/#',$file,$m))$group='theme:'.$m[1]; elseif(strpos($file,'/wp-includes/')!==false||strpos($file,'/wp-admin/')!==false)$group='wordpress-core'; else $group='other'; if(!isset($groups[$group]))$groups[$group]=0;$groups[$group]++; }arsort($groups);return array_slice($groups,0,30,true); } private function utc_timestamp($time){$ms=(int)(($time-floor($time))*1000);return gmdate('Y-m-d\TH:i:s',(int)$time).'.'.sprintf('%03d',$ms).'Z';} private function server_value($key,$limit=1000){if(!isset($_SERVER[$key])||!is_scalar($_SERVER[$key]))return null;$v=(string)$_SERVER[$key];return $v===''?null:substr($v,0,$limit);} private function get_log_dir(){return WP_CONTENT_DIR.'/rocket-request-tracer';} private function get_log_file(){ $dir=$this->get_log_dir();if(!is_dir($dir))@wp_mkdir_p($dir);$seed=defined('AUTH_SALT')?AUTH_SALT:ABSPATH;$suffix=substr(hash('sha256',$seed),0,16);return $dir.'/trace-'.$suffix.'.php'; } private function ensure_log_file(){ $dir=$this->get_log_dir();if(!is_dir($dir))@wp_mkdir_p($dir); if(!file_exists($dir.'/index.php'))@file_put_contents($dir.'/index.php',"<?php\nexit;\n"); if(!file_exists($dir.'/.htaccess'))@file_put_contents($dir.'/.htaccess',"Require all denied\nDeny from all\n"); if(!file_exists($this->log_file))@file_put_contents($this->log_file,"<?php exit; __halt_compiler(); ?>\n",LOCK_EX); } private function maybe_rotate(){ $max_mb=max(1,(int)get_option(self::OPT_MAX_MB,25)); if(file_exists($this->log_file)&&filesize($this->log_file)>($max_mb*1048576)){ $rotated=preg_replace('/\.php$/','-'.gmdate('Ymd-His').'.php',$this->log_file);@rename($this->log_file,$rotated);$this->ensure_log_file(); $files=glob($this->get_log_dir().'/trace-*.php');if(is_array($files)&&count($files)>4){usort($files,function($a,$b){return filemtime($a)<=>filemtime($b);});while(count($files)>4){$oldest=array_shift($files);if($oldest!==$this->log_file)@unlink($oldest);}} } } private function write_event($event){$this->ensure_log_file();$this->maybe_rotate();$json=wp_json_encode($event,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($json!==false)@file_put_contents($this->log_file,$json."\n",FILE_APPEND|LOCK_EX);} public function admin_menu(){add_management_page('Request Tracer','Request Tracer','manage_options','rocket-request-tracer',array($this,'render_admin'));} public function handle_save(){ if(!current_user_can('manage_options'))wp_die('Insufficient permissions.');check_admin_referer(self::NONCE); update_option(self::OPT_ENABLED,!empty($_POST['enabled'])?1:0,false);update_option(self::OPT_DEEP,!empty($_POST['deep'])?1:0,false); $max=isset($_POST['max_mb'])?max(1,min(250,(int)$_POST['max_mb'])):25;update_option(self::OPT_MAX_MB,$max,false); wp_safe_redirect(admin_url('tools.php?page=rocket-request-tracer'));exit; } public function handle_clear(){if(!current_user_can('manage_options'))wp_die('Insufficient permissions.');check_admin_referer(self::NONCE);$this->ensure_log_file();@file_put_contents($this->log_file,"<?php exit; __halt_compiler(); ?>\n",LOCK_EX);wp_safe_redirect(admin_url('tools.php?page=rocket-request-tracer'));exit;} public function handle_download(){ if(!current_user_can('manage_options'))wp_die('Insufficient permissions.');check_admin_referer(self::NONCE);$this->ensure_log_file(); header('Content-Type: application/x-ndjson');header('Content-Disposition: attachment; filename="rocket-request-trace-'.gmdate('Ymd-His').'.jsonl"'); $fh=@fopen($this->log_file,'rb');if($fh){fgets($fh);while(!feof($fh))echo fread($fh,1048576);fclose($fh);}exit; } private function read_events($limit=12000){ $this->ensure_log_file();$lines=@file($this->log_file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if(!is_array($lines))return array(); if(isset($lines[0])&&strpos($lines[0],'__halt_compiler')!==false)array_shift($lines);if(count($lines)>$limit)$lines=array_slice($lines,-$limit); $events=array();foreach($lines as $line){$d=json_decode($line,true);if(is_array($d)&&!empty($d['request_id']))$events[]=$d;}return $events; } private function build_rows($events){ $pairs=array();foreach($events as $e){$id=$e['request_id'];if(!isset($pairs[$id]))$pairs[$id]=array();if($e['event']==='START')$pairs[$id]['start']=$e;elseif($e['event']==='END')$pairs[$id]['end']=$e;} $rows=array();foreach($pairs as $id=>$pair){if(empty($pair['start']))continue;$s=$pair['start'];$e=isset($pair['end'])?$pair['end']:null; $rows[]=array( 'request_id'=>$id,'timestamp'=>isset($s['timestamp'])?$s['timestamp']:'','pid'=>isset($s['pid'])?(int)$s['pid']:0, 'method'=>isset($s['method'])?$s['method']:'','path'=>isset($s['path'])?$s['path']:'', 'action'=>!empty($s['wp_action'])?$s['wp_action']:(!empty($s['wc_ajax'])?'wc-ajax:'.$s['wc_ajax']:''), 'query'=>!empty($s['safe_query'])?wp_json_encode($s['safe_query'],JSON_UNESCAPED_SLASHES):'', 'ip'=>isset($s['client_ip'])?$s['client_ip']:'','cf_ray'=>isset($s['cf_ray'])?$s['cf_ray']:'', 'wall_ms'=>$e&&isset($e['wall_ms'])?(float)$e['wall_ms']:null,'cpu_ms'=>$e&&isset($e['cpu_total_ms'])?(float)$e['cpu_total_ms']:null, 'cpu_ratio'=>$e&&isset($e['cpu_ratio'])?(float)$e['cpu_ratio']:null,'classification'=>$e&&isset($e['classification'])?$e['classification']:'ACTIVE', 'memory_mb'=>$e&&isset($e['peak_memory_mb'])?(float)$e['peak_memory_mb']:null,'files'=>$e&&isset($e['included_files'])?(int)$e['included_files']:null, 'resources'=>$e&&isset($e['resources'])?$e['resources']:array(),'sql'=>$e&&isset($e['sql'])?$e['sql']:array(),'http'=>$e&&isset($e['http'])?$e['http']:array(), 'groups'=>$e&&isset($e['included_groups'])?$e['included_groups']:array(),'fatal'=>$e&&isset($e['fatal'])?$e['fatal']:null, 'state'=>$e?'DONE':'ACTIVE','deep'=>!empty($s['deep']) ); } usort($rows,function($a,$b){if($a['state']!==$b['state'])return $a['state']==='ACTIVE'?-1:1;if($a['state']==='ACTIVE')return strcmp($b['timestamp'],$a['timestamp']);return ($b['cpu_ms']?:0)<=>($a['cpu_ms']?:0);}); return $rows; } private function build_path_summary($rows){ $g=array();foreach($rows as $r){if($r['state']!=='DONE')continue;$p=$r['path']?:'(unknown)';if(!isset($g[$p]))$g[$p]=array('path'=>$p,'count'=>0,'wall_total'=>0,'cpu_total'=>0,'max_cpu'=>0,'cpu_bound'=>0,'wait_bound'=>0); $g[$p]['count']++;$g[$p]['wall_total']+=(float)$r['wall_ms'];$g[$p]['cpu_total']+=(float)$r['cpu_ms'];$g[$p]['max_cpu']=max($g[$p]['max_cpu'],(float)$r['cpu_ms']);if($r['classification']==='CPU_BOUND')$g[$p]['cpu_bound']++;if($r['classification']==='WAIT_BOUND')$g[$p]['wait_bound']++; } foreach($g as &$x){$x['avg_wall']=$x['count']?$x['wall_total']/$x['count']:0;$x['avg_cpu']=$x['count']?$x['cpu_total']/$x['count']:0;}unset($x); uasort($g,function($a,$b){return $b['avg_cpu']<=>$a['avg_cpu'];});return array_slice(array_values($g),0,15); } private function request_age_seconds($timestamp){$ts=strtotime(substr($timestamp,0,19).'Z');return $ts?max(0,time()-$ts):null;} private function bytes_human($bytes){return ($bytes===null||$bytes==='')?'—':size_format(max(0,(float)$bytes));} private function class_badge($c){$m=array('CPU_BOUND'=>'#b32d2e','WAIT_BOUND'=>'#996800','MIXED'=>'#7a5b00','FAST'=>'#2271b1','ACTIVE'=>'#8a2424','UNKNOWN'=>'#646970');$color=isset($m[$c])?$m[$c]:'#646970';return '<span style="display:inline-block;padding:2px 7px;border-radius:12px;background:'.esc_attr($color).';color:#fff;font-size:11px;font-weight:700;">'.esc_html($c).'</span>';} private function render_detail($row){ echo '<details><summary style="cursor:pointer;">Inspect</summary><div style="min-width:680px;padding:8px 0;">'; if($row['state']==='ACTIVE'){ $pid=(int)$row['pid'];echo '<p><strong>Live PID commands</strong></p>'; echo '<p><code>ps -p '.$pid.' -o pid,ppid,user,stat,etime,time,%cpu,%mem,rss,wchan:32,cmd</code></p>'; echo '<p><code>timeout 5 strace -f -ttT -s 256 -p '.$pid.'</code></p>'; echo '<p><code>sudo phpspy --pid='.$pid.' --limit=200</code></p>'; echo '<p><code>lsof -nP -p '.$pid.'</code></p>'; echo '</div></details>';return; } echo '<p><strong>Resource deltas</strong></p><pre style="white-space:pre-wrap;">'.esc_html(wp_json_encode($row['resources'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; echo '<p><strong>Included code ownership</strong></p><pre style="white-space:pre-wrap;">'.esc_html(wp_json_encode($row['groups'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; if($row['deep']){ $sql=$row['sql'];$http=$row['http'];echo '<p><strong>SQL:</strong> '.esc_html(isset($sql['count'])?$sql['count']:0).' captured; '.esc_html(isset($sql['total_ms'])?number_format_i18n($sql['total_ms'],1):'0').' ms total.</p>'; if(!empty($sql['top']))echo '<pre style="white-space:pre-wrap;">'.esc_html(wp_json_encode($sql['top'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; echo '<p><strong>Outbound HTTP:</strong> '.esc_html(isset($http['count'])?$http['count']:0).' captured; '.esc_html(isset($http['total_ms'])?number_format_i18n($http['total_ms'],1):'0').' ms total.</p>'; if(!empty($http['top']))echo '<pre style="white-space:pre-wrap;">'.esc_html(wp_json_encode($http['top'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; }else echo '<p><em>Deep attribution was disabled for this request.</em></p>'; if(!empty($row['fatal']))echo '<p><strong>Fatal shutdown error</strong></p><pre>'.esc_html(wp_json_encode($row['fatal'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</pre>'; echo '</div></details>'; } public function render_admin(){ if(!current_user_can('manage_options'))return; $events=$this->read_events();$rows=$this->build_rows($events);$paths=$this->build_path_summary($rows); $enabled=(bool)get_option(self::OPT_ENABLED,false);$deep=(bool)get_option(self::OPT_DEEP,false);$max=(int)get_option(self::OPT_MAX_MB,25);$size=file_exists($this->log_file)?filesize($this->log_file):0; $active=$done=$cpu_bound=$wait_bound=0;foreach($rows as $r){if($r['state']==='ACTIVE')$active++;else{$done++;if($r['classification']==='CPU_BOUND')$cpu_bound++;elseif($r['classification']==='WAIT_BOUND')$wait_bound++;}} ?>
        <div class="wrap">
        <h1>Rocket Request Tracer <small style="font-size:14px;color:#646970;">v<?php echo esc_html(self::VERSION); ?></small></h1>
        <p>Correlates WordPress requests with their PHP PID and separates CPU-heavy application work from requests primarily waiting on dependencies.</p>
        <div style="display:flex;gap:12px;flex-wrap:wrap;margin:16px 0;">
        <?php foreach(array(array('Tracing',$enabled?'ENABLED':'Disabled'),array('Active requests',$active),array('Completed',$done),array('CPU-bound',$cpu_bound),array('Wait-bound',$wait_bound),array('Log size',size_format($size))) as $card): ?>
          <div style="background:#fff;border:1px solid #ccd0d4;padding:12px 16px;min-width:130px;"><div style="color:#646970;font-size:12px;"><?php echo esc_html($card[0]); ?></div><div style="font-size:20px;font-weight:700;margin-top:3px;"><?php echo esc_html($card[1]); ?></div></div>
        <?php endforeach; ?>
        </div>
        <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="background:#fff;border:1px solid #ccd0d4;padding:14px 16px;margin:16px 0;">
          <?php wp_nonce_field(self::NONCE); ?><input type="hidden" name="action" value="rrt_save">
          <label style="margin-right:22px;"><input type="checkbox" name="enabled" value="1" <?php checked($enabled); ?>> <strong>Enable tracing</strong></label>
          <label style="margin-right:22px;"><input type="checkbox" name="deep" value="1" <?php checked($deep); ?>> <strong>Deep attribution</strong> (SQL + outbound HTTP caller data)</label>
          <label>Max active log: <input type="number" name="max_mb" value="<?php echo esc_attr($max); ?>" min="1" max="250" style="width:75px;"> MB</label>
          <?php submit_button('Save settings','primary','submit',false); ?>
          <p style="margin-bottom:0;color:#646970;">Deep attribution enables <code>$wpdb-&gt;save_queries</code> for traced requests. Use it for short production diagnostic windows.</p>
        </form>
        <p><a class="button" href="<?php echo esc_url(admin_url('tools.php?page=rocket-request-tracer')); ?>">Refresh</a>
        <a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=rrt_download'),self::NONCE)); ?>">Download JSONL</a>
        <a class="button" onclick="return confirm('Clear the trace log?');" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=rrt_clear'),self::NONCE)); ?>">Clear Log</a></p>

        <h2>Expensive paths</h2><div style="overflow:auto;background:#fff;border:1px solid #ccd0d4;margin-bottom:22px;"><table class="widefat striped"><thead><tr><th>Path</th><th>Requests</th><th>Avg wall</th><th>Avg CPU</th><th>Max CPU</th><th>CPU-bound</th><th>Wait-bound</th></tr></thead><tbody>
        <?php foreach($paths as $p): ?><tr><td><code><?php echo esc_html($p['path']); ?></code></td><td><?php echo esc_html($p['count']); ?></td><td><?php echo esc_html(number_format_i18n($p['avg_wall'],1)); ?> ms</td><td><?php echo esc_html(number_format_i18n($p['avg_cpu'],1)); ?> ms</td><td><?php echo esc_html(number_format_i18n($p['max_cpu'],1)); ?> ms</td><td><?php echo esc_html($p['cpu_bound']); ?></td><td><?php echo esc_html($p['wait_bound']); ?></td></tr><?php endforeach; ?>
        </tbody></table></div>

        <h2>Requests</h2><p>Active requests appear first. Completed requests are ordered by PHP CPU time.</p>
        <div style="overflow:auto;background:#fff;border:1px solid #ccd0d4;"><table class="widefat striped" style="min-width:1900px;"><thead><tr><th>Class</th><th>Age/UTC</th><th>PID</th><th>Method</th><th>Path</th><th>Action</th><th>Safe query</th><th>Wall</th><th>CPU</th><th>CPU %</th><th>Peak MB</th><th>SQL</th><th>HTTP</th><th>Read I/O</th><th>Write I/O</th><th>Files</th><th>IP</th><th>CF-Ray</th><th>Details</th></tr></thead><tbody>
        <?php foreach(array_slice($rows,0,300) as $r): ?>
        <tr><td><?php echo $this->class_badge($r['classification']); ?></td><td><?php if($r['state']==='ACTIVE'){$age=$this->request_age_seconds($r['timestamp']);echo esc_html(($age!==null?$age:'?').'s active').'<br>'; } ?><small><?php echo esc_html($r['timestamp']); ?></small></td><td><code><?php echo esc_html($r['pid']); ?></code></td><td><?php echo esc_html($r['method']); ?></td><td><code><?php echo esc_html($r['path']); ?></code></td><td><code><?php echo esc_html($r['action']); ?></code></td><td><code><?php echo esc_html($r['query']); ?></code></td>
        <td><?php echo $r['wall_ms']!==null?esc_html(number_format_i18n($r['wall_ms'],1).' ms'):'—'; ?></td><td><?php echo $r['cpu_ms']!==null?esc_html(number_format_i18n($r['cpu_ms'],1).' ms'):'—'; ?></td><td><?php echo $r['cpu_ratio']!==null?esc_html(number_format_i18n($r['cpu_ratio']*100,1).'%'):'—'; ?></td><td><?php echo $r['memory_mb']!==null?esc_html(number_format_i18n($r['memory_mb'],1)):'—'; ?></td>
        <td><?php if($r['deep']&&$r['state']==='DONE'){echo esc_html((isset($r['sql']['count'])?$r['sql']['count']:0).' / '.number_format_i18n(isset($r['sql']['total_ms'])?$r['sql']['total_ms']:0,1).' ms');}else echo '—'; ?></td>
        <td><?php if($r['deep']&&$r['state']==='DONE'){echo esc_html((isset($r['http']['count'])?$r['http']['count']:0).' / '.number_format_i18n(isset($r['http']['total_ms'])?$r['http']['total_ms']:0,1).' ms');}else echo '—'; ?></td>
        <td><?php echo esc_html($this->bytes_human(isset($r['resources']['read_bytes'])?$r['resources']['read_bytes']:null)); ?></td><td><?php echo esc_html($this->bytes_human(isset($r['resources']['write_bytes'])?$r['resources']['write_bytes']:null)); ?></td><td><?php echo $r['files']!==null?esc_html($r['files']):'—'; ?></td><td><?php echo esc_html($r['ip']); ?></td><td><code><?php echo esc_html($r['cf_ray']); ?></code></td><td><?php $this->render_detail($r); ?></td></tr>
        <?php endforeach; ?></tbody></table></div>
        <h2>Interpretation</h2><p><strong>CPU-bound:</strong> PHP is actively consuming CPU for most of the request. <strong>Wait-bound:</strong> wall time is much larger than PHP CPU time. For ACTIVE rows, open <strong>Inspect</strong> for commands pre-filled with the exact PID.</p>
        </div>
        <?php
 } } Rocket_Request_Tracer::instance();
